<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth.js';import {errorText} from '../services/api.js';const router=useRouter(),auth=useAuth();const register=ref(false),busy=ref(false),error=ref(''),form=ref({name:'',email:'',password:''});async function submit(){busy.value=true;error.value='';try{await auth.login(form.value,register.value);router.push('/');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}</script><template><v-container class="d-flex align-center justify-center" style="min-height:80vh"><v-card class="soft-card pa-7" width="460" elevation="0"><div class="text-center mb-6"><v-icon size="52" color="primary">mdi-account-group</v-icon><h1 class="text-h5 font-weight-bold mt-2">{{register?'สมัครสมาชิก SplitTrip':'ยินดีต้อนรับสู่ SplitTrip'}}</h1><p class="muted">จัดการค่าใช้จ่ายร่วมกันอย่างง่ายดาย</p></div><v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert><v-form @submit.prevent="submit"><v-text-field v-if="register" v-model="form.name" label="ชื่อที่แสดง" variant="outlined" required/><v-text-field v-model="form.email" label="อีเมล" type="email" variant="outlined" required/><v-text-field v-model="form.password" label="รหัสผ่าน (อย่างน้อย 8 ตัวอักษร)" type="password" variant="outlined" required minlength="8"/><v-btn type="submit" color="primary" block size="large" :loading="busy">{{register?'สมัครสมาชิก':'เข้าสู่ระบบ'}}</v-btn></v-form><v-btn variant="text" block class="mt-3" @click="register=!register;error=''">{{register?'มีบัญชีแล้ว? เข้าสู่ระบบ':'ยังไม่มีบัญชี? สมัครสมาชิก'}}</v-btn></v-card></v-container></template>